    "r": ((-1, -1), (-1, 1)),
    "w": ((1, -1), (1, 1)),
    "R": ((-1, -1), (-1, 1), (1, -1), (1, 1)),
    "W": ((-1, -1), (-1, 1), (1, -1), (1, 1)),
}
NAMES = {"r": "Red", "w": "White"}


def new_board():
    b = [["." for _ in range(BOARD_SIZE)] for _ in range(BOARD_SIZE)]
    for r in range(BOARD_SIZE):
        for c in range(BOARD_SIZE):
            if (r + c) % 2:
                if r < 3:
                    b[r][c] = "w"
                elif r > 4:
                    b[r][c] = "r"
    return b


def parse_square(text):
    text = text.strip().lower()
    if len(text) == 2 and text[0].isalpha() and text[1].isdigit():
        c = ord(text[0]) - 97
        r = BOARD_SIZE - int(text[1])
        if 0 <= r < BOARD_SIZE and 0 <= c < BOARD_SIZE:
            return (r, c)
    return None


def piece_moves(b, r, c, capture_only=False):
    p = b[r][c]
    out = []
    for dr, dc in DIRS[p]:
        r1, c1 = r + dr, c + dc
        if not (0 <= r1 < BOARD_SIZE and 0 <= c1 < BOARD_SIZE):
            continue
        t = b[r1][c1]
        if t == ".":
            if not capture_only:
                out.append((r1, c1, None))
        elif t.lower() != p.lower():
            r2, c2 = r + 2 * dr, c + 2 * dc
            if 0 <= r2 < BOARD_SIZE and 0 <= c2 < BOARD_SIZE and b[r2][c2] == ".":
                out.append((r2, c2, (r1, c1)))
    return out


def all_moves(b, player, capture_only=False, only=None):
    moves = {}
    for r in range(BOARD_SIZE):
        for c in range(BOARD_SIZE):
            if only is not None and (r, c) != only:
                continue
            if b[r][c].lower() == player and b[r][c] != ".":
                ms = piece_moves(b, r, c, capture_only)
                if ms:
                    moves[(r, c)] = ms
    return moves


def print_board(b):
