    for i, row in enumerate(b):
        print(f" {BOARD_SIZE - i} " + " ".join(row) + f"  {BOARD_SIZE - i}")
    print("   a b c d e f g h")


def apply_move(b, src, dst, cap):
    p = b[src[0]][src[1]]
    b[src[0]][src[1]] = "."
